PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE provider_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), business_name TEXT, category TEXT NOT NULL, service_ids TEXT NOT NULL, locations TEXT NOT NULL, description TEXT NOT NULL, experience INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')), online INTEGER NOT NULL DEFAULT 0, schedule TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0), type TEXT NOT NULL, icon TEXT NOT NULL DEFAULT '🔧', tone TEXT NOT NULL DEFAULT 'blue', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE addresses (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, address TEXT NOT NULL, location TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bookings (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES users(id), service_id TEXT NOT NULL REFERENCES services(id), provider_id TEXT REFERENCES provider_profiles(user_id), location TEXT NOT NULL, address TEXT NOT NULL, scheduled_at TEXT NOT NULL, description TEXT NOT NULL, details TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'requested', estimated_price INTEGER NOT NULL DEFAULT 0, payment_method TEXT NOT NULL DEFAULT 'cash', payment_status TEXT NOT NULL DEFAULT 'pending', idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(customer_id,idempotency_key));
CREATE INDEX bookings_customer ON bookings(customer_id,created_at);
CREATE INDEX bookings_provider ON bookings(provider_id,status);
CREATE TABLE booking_status_history (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), actor_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE booking_rejections (booking_id TEXT NOT NULL REFERENCES bookings(id), provider_id TEXT NOT NULL REFERENCES provider_profiles(user_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(booking_id,provider_id));
CREATE TABLE quotations (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), provider_id TEXT NOT NULL REFERENCES provider_profiles(user_id), labour INTEGER NOT NULL CHECK(labour>=0), materials INTEGER NOT NULL CHECK(materials>=0), additional INTEGER NOT NULL DEFAULT 0 CHECK(additional>=0), terms TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE messages (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), sender_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX messages_booking ON messages(booking_id,created_at);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, booking_id TEXT REFERENCES bookings(id), is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL UNIQUE REFERENCES bookings(id), customer_id TEXT NOT NULL REFERENCES users(id), provider_id TEXT NOT NULL REFERENCES provider_profiles(user_id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), amount INTEGER NOT NULL CHECK(amount>=0), gateway_order_id TEXT UNIQUE, gateway_payment_id TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE support_tickets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), booking_id TEXT REFERENCES bookings(id), subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', resolution TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE favourites (user_id TEXT NOT NULL REFERENCES users(id), provider_id TEXT NOT NULL REFERENCES provider_profiles(user_id), PRIMARY KEY(user_id,provider_id));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE admin_activity_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE uploads (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), booking_id TEXT REFERENCES bookings(id), object_key TEXT NOT NULL, content_type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE request_windows (user_id TEXT NOT NULL REFERENCES users(id), window INTEGER NOT NULL, hits INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,window));
